using Dapper;
using SubscriptionPlatform.Api.Data;

namespace SubscriptionPlatform.Api.Repositories;

public sealed class PaymentRepository(ConnectionFactory connections)
{
    public async Task<bool> VerifyAndActivateAsync(Guid appId,Guid paymentId,string orderId,string paymentProviderId){await using var db=connections.Create();await db.OpenAsync();await using var tx=await db.BeginTransactionAsync();var p=await db.QuerySingleOrDefaultAsync<dynamic>("SELECT p.*,s.application_id,s.billing_period,s.status sub_status FROM payments p JOIN subscriptions s ON s.id=p.subscription_id WHERE p.id=@paymentId AND s.application_id=@appId FOR UPDATE",new{paymentId,appId},tx);if(p is null)return false;if((string)p.status=="paid")return true;if((string?)p.razorpay_order_id!=orderId)return false;var now=DateTime.UtcNow;var end=(string)p.billing_period=="yearly"?now.AddYears(1):now.AddMonths(1);await db.ExecuteAsync("UPDATE payments SET status='paid',razorpay_payment_id=@providerId,paid_utc=@now WHERE id=@paymentId",new{providerId=paymentProviderId,now,paymentId},tx);await db.ExecuteAsync("UPDATE subscriptions SET status='active',starts_utc=@now,ends_utc=@end,version=version+1 WHERE id=@sid",new{now,end,sid=(Guid)p.subscription_id},tx);await db.ExecuteAsync("INSERT INTO subscription_audits(subscription_id,from_status,to_status,reason,at_utc) VALUES(@sid,@from,'active','razorpay_signature_verified',@now)",new{sid=(Guid)p.subscription_id,from=(string)p.sub_status,now},tx);await tx.CommitAsync();return true;}
    public async Task<IEnumerable<object>> HistoryAsync(Guid appId){await using var db=connections.Create();return await db.QueryAsync("SELECT p.id,p.subscription_id,p.amount_minor,p.currency,p.status,p.created_utc,p.paid_utc FROM payments p JOIN subscriptions s ON s.id=p.subscription_id WHERE s.application_id=@appId",new{appId});}
    public async Task<bool> ProcessWebhookAsync(string eventId,string eventType,string? orderId,string? paymentProviderId){await using var db=connections.Create();await db.OpenAsync();await using var tx=await db.BeginTransactionAsync();if(await db.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM webhook_events WHERE event_id=@eventId",new{eventId},tx)>0){await tx.CommitAsync();return false;}await db.ExecuteAsync("INSERT INTO webhook_events(event_id,event_type,received_utc) VALUES(@eventId,@eventType,UTC_TIMESTAMP(6))",new{eventId,eventType},tx);if(eventType is "payment.captured" or "payment.failed"){var p=await db.QuerySingleOrDefaultAsync<dynamic>("SELECT p.id,p.subscription_id,p.status,s.billing_period,s.status sub_status FROM payments p JOIN subscriptions s ON s.id=p.subscription_id WHERE p.razorpay_order_id=@orderId FOR UPDATE",new{orderId},tx);if(p is not null){if(eventType=="payment.captured"&&(string)p.status!="paid"){var now=DateTime.UtcNow;var end=(string)p.billing_period=="yearly"?now.AddYears(1):now.AddMonths(1);await db.ExecuteAsync("UPDATE payments SET status='paid',razorpay_payment_id=@paymentProviderId,paid_utc=@now WHERE id=@id",new{paymentProviderId,now,id=(Guid)p.id},tx);await db.ExecuteAsync("UPDATE subscriptions SET status='active',starts_utc=@now,ends_utc=@end,version=version+1 WHERE id=@sid",new{now,end,sid=(Guid)p.subscription_id},tx);await db.ExecuteAsync("INSERT INTO subscription_audits(subscription_id,from_status,to_status,reason,at_utc) VALUES(@sid,@from,'active','verified_webhook',@now)",new{sid=(Guid)p.subscription_id,from=(string)p.sub_status,now},tx);}else if(eventType=="payment.failed"&&(string)p.status!="paid"){await db.ExecuteAsync("UPDATE payments SET status='failed' WHERE id=@id",new{id=(Guid)p.id},tx);await db.ExecuteAsync("UPDATE subscriptions SET status='grace',grace_ends_utc=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 3 DAY),version=version+1 WHERE id=@sid",new{sid=(Guid)p.subscription_id},tx);}}}await tx.CommitAsync();return true;}
}
